 "content": "def transform(grid):
    """Project each solid 3x3 block's color along its center row and column."""
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3)
                   for cc in range(c, c + 3)):
                centers.append((r + 1, c + 1, color))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            colors = set()
            for cr, cc, color in centers:
                if r == cr or c == cc:
                    colors.add(color)
            if len(colors) == 1:
                out[r][c] = next(iter(colors))
            elif len(colors) > 1:
                out[r][c] = 0
    return out
